style.ha-state-control-climate-temperature $:
.info { gap: 0 !important; padding-bottom: 34px !important; }
.info > .label:not(.secondary) { display: none !important; }
.info::before { content: "{% set s = states('climate.khdr_shynh_hvrym') %}{{ {'off': 'כבוי', 'cool': 'קירור', 'heat': 'חימום', 'dry': 'ייבוש', 'fan_only': 'אוורור', 'heat_cool': 'אוטומטי', 'auto': 'אוטומטי', 'unavailable': 'לא זמין'}.get(s, s) }}" !important; font-size: 12.5px !important; font-weight: 600 !important; line-height: 1 !important; padding: 6px 12px !important; border-radius: 99px !important; margin-bottom: 6px !important; color: color-mix(in srgb, var(--state-color) 72%, var(--primary-text-color)) !important; background: color-mix(in srgb, var(--state-color) 20%, transparent) !important; }
ha-big-number { font-size: 92px !important; font-weight: 300 !important; letter-spacing: -4px !important; line-height: 1 !important; }
.label.secondary { display: block !important; direction: rtl !important; width: auto !important; min-height: 0 !important; margin-top: 4px !important; font-size: 13px !important; font-weight: 400 !important; color: var(--secondary-text-color) !important; }
.label.secondary ha-svg-icon { display: none !important; }
.label.secondary::before { content: 'בחדר עכשיו \2066' !important; }
.buttons { bottom: 6px !important; gap: 20px !important; }
.buttons ha-outlined-icon-button { --ha-icon-button-size: 46px !important; --ha-outlined-icon-button-outline-color: transparent !important; background: var(--card-background-color) !important; border-radius: 50% !important; color: var(--primary-text-color) !important; }
ha-control-circular-slider { position: relative !important; --control-circular-slider-background: color-mix(in srgb, var(--secondary-text-color) 22%, var(--card-background-color)) !important; --control-circular-slider-background-opacity: 1 !important; }
ha-control-circular-slider::before { content: '' !important; position: absolute !important; inset: 9.5% !important; border-radius: 50% !important; pointer-events: none !important; opacity: .38 !important; background: repeating-conic-gradient(from 224.6deg, var(--secondary-text-color) 0 .8deg, transparent .8deg 7.5deg) !important; -webkit-mask: radial-gradient(closest-side, transparent calc(100% - 7px), #000 calc(100% - 6px)), conic-gradient(from 224deg, #000 0 272deg, transparent 272deg) !important; -webkit-mask-composite: source-in !important; mask-composite: intersect !important; }
ha-control-circular-slider::after { inset: 0 !important; opacity: .24 !important; background: radial-gradient(closest-side, var(--action-color, transparent) 0%, transparent 84%) !important; }

style.ha-state-control-climate-temperature $ h:
.addon { width: 0 !important; overflow: visible !important; padding: 0 !important; align-self: flex-start !important; }
.unit { font-size: 0 !important; }
.unit::before { content: '°' !important; font-size: 44px !important; font-weight: 300 !important; letter-spacing: 0 !important; color: var(--secondary-text-color) !important; }

.background, .arc { stroke-width: 6px !important; }
.arc-colored { opacity: 1 !important; filter: drop-shadow(0 0 5px var(--control-circular-slider-color)) !important; }
.inactive .arc-colored { opacity: 0 !important; filter: none !important; }
.target-border { stroke-width: 24px !important; }
.target { stroke-width: 13px !important; }
.current { stroke-width: 11px !important; opacity: .9 !important; }

